declaration:
FUNCTION_BLOCK FB

VAR_INPUT
    tankLevel : REAL;
    outletFlow : REAL;
    inletPermit : BOOL;
    resetBtn : BOOL;
END_VAR
VAR_OUTPUT
    pumpRun : BOOL;
    alarmHigh : BOOL;
    alarmLow : BOOL;
    outletValveOpen : BOOL;
END_VAR
VAR
    resetPrev : BOOL;
    resetEdge : BOOL;
    latchReset : BOOL;
END_VAR

implementation:
resetEdge := resetBtn AND NOT resetPrev;
resetPrev := resetBtn;
latchReset := resetEdge;



IF tankLevel >= 85.0 THEN
    alarmHigh := TRUE;
END_IF

IF latchReset AND tankLevel < 85.0 THEN
    alarmHigh := FALSE;
END_IF
IF tankLevel <= 15.0 THEN
    alarmLow := TRUE;
END_IF
IF latchReset AND tankLevel > 15.0 THEN
    alarmLow := FALSE;
END_IF


pumpRun := inletPermit AND NOT alarmHigh AND NOT alarmLow
           AND tankLevel < 85.0 AND tankLevel >= 15.0;


outletValveOpen := NOT alarmLow;
